export function flagLaborValue(params) {
  const value = Number(params?.value);
  const refMin = Number(params?.referenceMin);
  const refMax = Number(params?.referenceMax);
  const criticalLow = Number(params?.criticalLow);
  const criticalHigh = Number(params?.criticalHigh);
  const has = (n) => Number.isFinite(n);
  if (!has(value)) return { flag: "unknown", tone: "neutral", critical: false, label: "Wert fehlt", display: "—" };
  let flag = "normal";
  let critical = false;
  if (has(criticalLow) && value <= criticalLow) { flag = "critical-low"; critical = true; }
  else if (has(criticalHigh) && value >= criticalHigh) { flag = "critical-high"; critical = true; }
  else if (has(refMin) && value < refMin) flag = "low";
  else if (has(refMax) && value > refMax) flag = "high";
  const labels = { normal: "im Referenzbereich", low: "erniedrigt", high: "erhöht", "critical-low": "kritisch niedrig", "critical-high": "kritisch hoch" };
  return {
    flag,
    tone: critical ? "danger" : flag === "normal" ? "success" : "warning",
    critical,
    label: labels[flag],
    display: String(value) + (params?.unit ? " " + params.unit : ""),
    reference: has(refMin) || has(refMax) ? String(has(refMin) ? refMin : "—") + "–" + String(has(refMax) ? refMax : "—") + (params?.unit ? " " + params.unit : "") : null
  };
}

export function assessAdministration(params) {
  const scheduled = params?.scheduledAt ? new Date(params.scheduledAt).getTime() : null;
  const administered = params?.administeredAt ? new Date(params.administeredAt).getTime() : null;
  const reference = params?.now ? new Date(params.now).getTime() : Date.now();
  if (params?.requiresDoubleCheck && !params?.doubleChecked) {
    return { status: "blocked", tone: "danger", minutesDelta: null, message: "Doppelkontrolle ausstehend" };
  }
  if (!scheduled || Number.isNaN(scheduled)) {
    return { status: "unscheduled", tone: "neutral", minutesDelta: null, message: "Keine geplante Gabezeit" };
  }
  const effective = administered && !Number.isNaN(administered) ? administered : reference;
  const minutesDelta = Math.round((effective - scheduled) / 60000);
  if (administered) {
    const onTime = Math.abs(minutesDelta) <= 30;
    return { status: onTime ? "administered-on-time" : "administered-deviating", tone: onTime ? "success" : "warning", minutesDelta, message: onTime ? "Zeitgerecht verabreicht" : "Zeitabweichung dokumentieren" };
  }
  if (minutesDelta > 60) return { status: "overdue", tone: "danger", minutesDelta, message: "Gabe überfällig" };
  if (minutesDelta >= -30) return { status: "due", tone: "warning", minutesDelta, message: "Gabe jetzt fällig" };
  return { status: "planned", tone: "info", minutesDelta, message: "Gabe geplant" };
}

export function validateIdentityConsistency(params) {
  const normalize = (value) => String(value ?? "").trim().toLocaleLowerCase("de-DE");
  const header = params?.header ?? {};
  const prefill = params?.prefill ?? {};
  const compared = ["name", "dateOfBirth", "patientId"];
  const mismatches = compared.filter((key) => {
    const left = normalize(header[key]);
    const right = normalize(prefill[key]);
    return left && right && left !== right;
  });
  const missing = compared.filter((key) => !normalize(header[key]) && !normalize(prefill[key]));
  const unknownIdentity = !normalize(header.patientId) || normalize(header.name).includes("unbekannt");
  const blocked = unknownIdentity || mismatches.length > 0;
  return {
    blocked,
    status: blocked ? "identity-conflict" : missing.length ? "incomplete" : "consistent",
    mismatches,
    missing,
    message: blocked ? "Patientenidentität widersprüchlich oder unbekannt – Vorgang stoppen." : missing.length ? "Identität unvollständig – vor Fortsetzung ergänzen." : "Identität konsistent."
  };
}

export function assessDirtyState(params) {
  const stable = (value) => {
    if (Array.isArray(value)) return value.map(stable);
    if (value && typeof value === "object") {
      return Object.keys(value).sort().reduce((out, key) => {
        if (!["updatedAt", "lastViewedAt", "_runtime"].includes(key)) out[key] = stable(value[key]);
        return out;
      }, {});
    }
    return value ?? null;
  };
  const baseline = JSON.stringify(stable(params?.baseline ?? {}));
  const current = JSON.stringify(stable(params?.current ?? {}));
  const dirty = baseline !== current;
  return {
    dirty,
    requiresDiscardConfirmation: dirty,
    canCloseSilently: !dirty,
    message: dirty ? "Ungespeicherte Änderungen vorhanden." : "Keine Änderungen."
  };
}
